const financeDocumentFields=type=>`<input type="hidden" name="document_type" value="${type}"><div class="field-row"><div class="field"><label>Invoice number</label><input name="document_number" required></div><div class="field"><label>Date</label><input type="date" name="document_date" required value="${today()}"></div></div><div class="field"><label>${type==='sales_invoice'?'Customer':'Supplier'}</label><input name="party_name" required></div><div class="field-row"><div class="field"><label>Net amount</label><input type="number" step="0.01" min="0" name="taxable_amount" required></div><div class="field"><label>VAT</label><input type="number" step="0.01" min="0" name="vat_amount" value="0"></div></div><div class="field"><label>Payment</label><select name="payment_status"><option value="unknown">Unknown</option><option value="unpaid">Unpaid</option><option value="paid">Paid</option><option value="part_paid">Part paid</option></select></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
const fields={task:()=>`<div class="field"><label>Task</label><input name="title" required placeholder="Prune upper block"></div><div class="field-row"><div class="field"><label>Due date</label><input type="date" name="due_date" value="${today()}"></div>${blockField()}</div>${categoryField()}<div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`,activity:()=>`<div class="field"><label>Work completed</label><input name="title" required placeholder="Mowed between rows"></div><div class="field-row"><div class="field"><label>Date</label><input type="date" name="activity_date" required value="${today()}"></div>${blockField()}</div>${categoryField()}<div class="field-row"><div class="field"><label>Hours</label><input type="number" step="0.25" min="0" name="labor_hours"></div><div class="field"><label>People</label><input type="number" min="0" name="worker_count"></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`,harvest:()=>`<div class="field-row"><div class="field"><label>Variety</label><select name="variety_id" required><option value="">Choose…</option>${state.reference.varieties.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></div>${blockField()}</div><div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="harvested_at" required value="${today()}T08:00"></div><div class="field"><label>Net weight (kg)</label><input type="number" step="0.1" min="0" name="weight_kg"></div></div><div class="field-row"><div class="field"><label>Crates</label><input type="number" min="0" name="crate_count"></div><div class="field"><label>Destination</label><input name="destination" placeholder="Tank or cellar"></div></div><details><summary>More details</summary><div class="field-row"><div class="field"><label>Lot code</label><input name="lot_code" placeholder="2026-GRC-01"></div><div class="field"><label>Fruit condition</label><select name="condition_grade"><option value="">Not recorded</option><option>Excellent</option><option>Good</option><option>Mixed</option><option>Compromised</option></select></div></div><div class="field-row"><div class="field"><label>Gross kg</label><input type="number" step="0.1" min="0" name="gross_kg"></div><div class="field"><label>Tare kg</label><input type="number" step="0.1" min="0" name="tare_kg"></div></div><div class="field-row"><div class="field"><label>Fruit temp °C</label><input type="number" step="0.1" name="fruit_temp_c"></div><div class="field"><label>°Babo</label><input type="number" step="0.1" min="0" name="babo"></div></div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><input type="hidden" name="status" value="received">`};
const harvestFieldsBase=fields.harvest;
fields.harvest=()=>harvestFieldsBase().replace('<div class="field"><label>Notes</label>',`<div class="field harvest-parcel-field"><label>Legal parcels included in this pick</label><input type="hidden" name="parcel_ids"><div class="check-grid parcel-pick-grid">${(state.reference?.parcels||[]).map(parcel=>`<label><input type="checkbox" data-harvest-parcel value="${esc(parcel.id)}"><span><b>${esc(parcel.municipality)} · Sheet ${esc(parcel.cadastral_sheet)} · Parcel ${esc(parcel.parcel_number)}</b><small>${known(parcel.official_vineyard_area_ha??parcel.conducted_area_ha??parcel.cadastral_area_ha,' ha')} · ${esc(parcel.tenure||'tenure not recorded')}</small></span></label>`).join('')||'<span class="empty">No legal parcels are configured in the Atlas.</span>'}</div><small>Select every cadastral parcel contributing grapes to this single picking lot.</small></div><div class="field"><label>Notes</label>`);
fields.purchase=()=>financeDocumentFields('purchase_invoice');
fields.sale=()=>financeDocumentFields('sales_invoice');
fields.cash=()=>`<div class="field-row"><div class="field"><label>Account</label><input name="account_name" required placeholder="Credit Agricole"></div><div class="field"><label>Date</label><input type="date" name="transaction_date" required value="${today()}"></div></div><div class="field"><label>Description</label><input name="description" required></div><div class="field"><label>Party</label><input name="party_name"></div><div class="field-row"><div class="field"><label>Money in</label><input type="number" step="0.01" min="0" name="amount_in" value="0"></div><div class="field"><label>Money out</label><input type="number" step="0.01" min="0" name="amount_out" value="0"></div></div><div class="field"><label>Type</label><select name="transaction_type"><option value="other">Other</option><option value="customer_receipt">Customer receipt</option><option value="supplier_payment">Supplier payment</option><option value="owner_contribution">Owner contribution</option><option value="owner_draw">Owner draw</option><option value="bank_fee">Bank fee</option><option value="tax">Tax</option><option value="transfer">Transfer</option><option value="refund">Refund</option></select></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
const choices=(rows,value,label,empty='Choose…')=>`<option value="">${empty}</option>${(rows||[]).map(row=>`<option value="${esc(row[value])}">${esc(row[label])}</option>`).join('')}`;
fields.cellar=()=>`<div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="operation_at" required value="${today()}T12:00"></div><div class="field"><label>Operation</label><select name="operation_type" required><option>Observation</option><option>Transfer</option><option>Addition</option><option>Racking</option><option>Pressing</option><option>Filtration</option><option>Bottling</option><option>Cleaning</option><option>Other</option></select></div></div><div class="field-row"><div class="field"><label>Wine lot</label><select name="wine_lot_id">${choices(state.reference.wine_lots,'id','code','No specific lot')}</select></div><div class="field"><label>Container</label><select name="container_id">${choices(state.reference.containers,'id','code','No specific container')}</select></div></div><div class="field-row"><div class="field"><label>Amount</label><input type="number" step="0.01" name="amount"></div><div class="field"><label>Unit</label><input name="unit" placeholder="L, kg, g/hL…"></div></div><div class="field"><label>Notes / observation</label><textarea name="notes"></textarea></div>`;
fields.scouting=()=>scoutingEntryFields();
fields.phenology=()=>`${blockField()}<div class="field-row"><div class="field"><label>Date</label><input type="date" name="observed_date" required value="${today()}"></div><div class="field"><label>Variety</label><select name="variety_id" required>${choices(state.reference.varieties,'id','name','Choose variety…')}</select></div></div><div class="field"><label>Growth stage</label><select name="stage_code" required><option value="">Choose growth stage…</option>${(state.reference?.phenology_stages||[]).map(stage=>`<option value="${esc(stage.code)}">${esc(stage.label)}</option>`).join('')}</select><small>Growth stage and completion evidence update the selected variety's harvest prediction.</small></div><div class="field observation-route-preview"><label>Processing pipeline</label><div>${((state.reference?.phenology_stages||[])[0]?.pipelines||[]).map((route,index)=>`<div><b>${index+1}. ${esc(route.label)}</b></div>`).join('')}</div><small>Photos validate visible stage evidence; laboratory maturity remains authoritative for chemistry.</small></div><div class="field"><label>Percent complete</label><input type="number" min="0" max="100" step="1" name="percent_complete"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
fields.treatment=()=>`<div class="field"><label>Crop program</label><select name="crop_scope"><option value="vineyard" ${state.treatmentCrop==='vineyard'?'selected':''}>Vineyard</option><option value="olives" ${state.treatmentCrop==='olives'?'selected':''}>Olives</option></select></div>${blockField()}<div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="application_date" required value="${today()}T08:00"></div><div class="field"><label>Status</label><select name="status"><option value="planned">Planned</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div></div><div class="field"><label>Purpose</label><input name="purpose" required></div><div class="field"><label>Product</label><select name="product_id">${choices(state.reference.products,'id','name','Choose if known')}</select></div><div class="field-row"><div class="field"><label>Dose</label><input type="number" step="0.001" name="dose_amount"></div><div class="field"><label>Dose unit</label><input name="dose_unit" placeholder="kg/ha, ml/L…"></div></div><details><summary>Completed-treatment checks</summary><div class="check-grid">${['agronomist_approved','label_legal_confirmed','phi_checked','rei_checked','weather_checked','ppe_confirmed','actual_details_confirmed'].map(name=>`<label><input type="checkbox" name="${name}"> ${name.replaceAll('_',' ')}</label>`).join('')}</div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
fields.lab=()=>`<div class="field-row"><div class="field"><label>Sample date</label><input type="date" name="lab_date" required value="${today()}"></div><div class="field"><label>Sample type</label><select name="sample_type"><option>grape</option><option>must</option><option selected>wine</option><option>soil</option><option>water</option><option>other</option></select></div></div><div class="field-row"><div class="field"><label>Grape variety</label><select name="variety_id">${choices(state.reference.varieties,'id','name','Required for grape samples')}</select><small>Grape reports must be assigned so the correct prediction updates.</small></div><div class="field"><label>Vintage</label><input type="number" name="vintage_year" min="2020" max="2100" value="${state.year}"></div></div><div class="field"><label>Sample / lot name</label><input name="sample_name" required></div><div class="field-row"><div class="field"><label>Analyte</label><input name="analyte_name" required placeholder="pH, TA, Brix, potential alcohol…"></div><div class="field"><label>Code</label><input name="analyte_code" required placeholder="ph, ta, brix…"></div></div><div class="field-row"><div class="field"><label>Value</label><input type="number" step="0.0001" name="numeric_value" required></div><div class="field"><label>Unit</label><input name="unit"></div></div><div class="field"><label>Laboratory / source</label><input name="laboratory"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
function laborWorkerChoices(){const fallback=['Giancarlo Pafumi','Luca Schiliro Cognato','Carmela Pafumi','Mattia','Nunzio'],saved=(state.adminControl?.labor_reconciliation||[]).map(row=>row.name),names=[...new Set([...saved,...fallback].map(value=>String(value||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));return names.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}
fields.labor=()=>`<section class="labor-entry-form">
  <div class="labor-entry-heading"><div><b>Labor or contractor service</b><small>One worker and one approval/payment record</small></div><span>Hourly or fixed price</span></div>
  <div class="labor-entry-context">
    <div class="field"><label>Entry type</label><select name="labor_entry_mode" data-labor-mode><option value="hourly">Hourly work</option><option value="fixed_job">Fixed-price job / service</option></select></div>
    <div class="field"><label>Worker type</label><select name="employment_class" data-labor-class><option value="contractor">Contractor</option><option value="seasonal_hourly">Seasonal hourly</option></select></div>
  </div>
  <div class="labor-entry-person">
    <div class="field"><label>Employee / worker</label><select name="person_or_crew" required data-labor-worker><option value="">Select worker…</option>${laborWorkerChoices()}<option value="__other__">Other / add contractor…</option></select><input name="custom_worker_name" data-labor-custom-worker autocomplete="off" placeholder="Contractor or worker name" hidden disabled></div>
    <div class="field"><label>Work date</label><input type="date" name="work_date" required value="${today()}"></div>
  </div>
  <div class="labor-entry-hours" data-labor-hourly>
    <div class="field labor-hours-primary"><label>Regular hours</label><div class="labor-number"><input type="number" inputmode="decimal" step="0.25" min="0" max="24" name="regular_hours" required placeholder="0.00"><span>h</span></div></div>
    <div class="field"><label>Overtime</label><div class="labor-number"><input type="number" inputmode="decimal" step="0.25" min="0" max="24" name="overtime_hours" value="0"><span>h</span></div></div>
    <div class="field"><label>Hourly rate</label><div class="labor-number labor-currency"><span>€</span><input type="number" inputmode="decimal" step="0.01" min="0" name="hourly_rate_eur" placeholder="Optional"></div></div>
  </div>
  <div class="labor-entry-hours" data-labor-fixed hidden><div class="field labor-hours-primary"><label>Agreed job cost</label><div class="labor-number labor-currency"><span>€</span><input type="number" inputmode="decimal" step="0.01" min="0.01" name="other_cost_eur" placeholder="0.00" disabled></div><small>No hours are required for a fixed-price service.</small></div><div class="field"><label>Service or expense type</label><select name="expense_category" disabled><option value="contractor_job">Contractor job</option><option value="water_delivery">Water delivery</option><option value="equipment">Equipment</option><option value="transport">Transport</option><option value="materials">Materials</option><option value="fuel">Fuel</option><option value="tools">Tools</option><option value="service">Other service</option><option value="other">Other</option></select></div></div>
  <div class="field"><label>Work or service performed</label><textarea name="work_performed" required rows="2" placeholder="Short description of the work or completed service"></textarea></div>
  <div class="labor-entry-context">
    <div class="field"><label>Work category</label><input name="work_category" placeholder="Vineyard, cellar, maintenance…"></div>
    <div class="field"><label>Location / parcel</label><input name="location_text" placeholder="Parcel, cellar or building"></div>
  </div>
  <details class="labor-entry-more"><summary>More details</summary><div class="labor-entry-more-grid">
    <div class="field"><label>Role</label><input name="role" value="Contractor" readonly></div>
    <input type="hidden" name="payroll_scope" value="contractor">
    <div class="field labor-notes"><label>Notes</label><textarea name="notes" rows="2" placeholder="Optional payroll, source or correction note"></textarea></div>
  </div></details>
</section>`;
fields.inventory=()=>`<div class="field"><label>Product</label><select name="product_id" required>${choices(state.reference.products,'id','name')}</select></div><div class="field-row"><div class="field"><label>Count date</label><input type="date" name="snapshot_date" required value="${today()}"></div><div class="field"><label>Quantity on hand</label><input type="number" step="0.001" min="0" name="quantity_on_hand" required></div></div><div class="field"><label>Stock value per unit €</label><input type="number" step="0.01" min="0" name="average_sales_price" placeholder="12.00"><small>Finished bottles default to €12 each; change this when the stock value changes.</small></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
fields.olive=()=>`<div class="field-row"><div class="field"><label>Date</label><input type="date" name="record_date" required value="${today()}"></div><div class="field"><label>Activity</label><select name="activity"><option>Field work</option><option>Treatment</option><option>Harvest</option><option>Milling</option><option>Oil inventory</option><option>Other</option></select></div></div><div class="field-row"><div class="field"><label>Olives kg</label><input type="number" step="0.1" name="olives_harvested_kg"></div><div class="field"><label>Oil liters</label><input type="number" step="0.1" name="oil_liters"></div></div><div class="field"><label>Details / notes</label><textarea name="notes"></textarea></div>`;
fields.issue=()=>`<div class="field-row"><div class="field"><label>Date</label><input type="date" name="opened_date" value="${today()}"></div><div class="field"><label>Priority</label><select name="priority"><option>low</option><option selected>medium</option><option>high</option><option>critical</option></select></div></div><div class="field"><label>Issue or decision</label><textarea name="issue_text" required></textarea></div><div class="field-row"><div class="field"><label>Owner</label><input name="owner_text"></div><div class="field"><label>Due date</label><input type="date" name="due_date"></div></div><div class="field"><label>Next action / decision</label><textarea name="decision_action"></textarea></div>`;
fields.maturity=()=>`<div class="field-row">${blockField()}<div class="field"><label>Variety</label><select name="variety_id" required>${choices(state.reference.varieties,'id','name','Choose variety…')}</select></div></div><div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="sampled_at" required value="${today()}T09:00"></div><div class="field"><label>Decision</label><select name="decision"><option value="monitor">Monitor</option><option value="resample">Resample</option><option value="hold">Hold</option><option value="ready">Ready for approval</option><option value="picked">Picked</option></select></div></div><div class="field-row"><div class="field"><label>°Brix</label><input type="number" step="0.1" name="brix"></div><div class="field"><label>pH</label><input type="number" step="0.01" name="ph"></div><div class="field"><label>TA g/L</label><input type="number" step="0.1" name="ta_g_l"></div></div><details><summary>More details</summary><div class="field-row"><div class="field"><label>Fruit temperature °C</label><input type="number" step="0.1" name="fruit_temp_c"></div><div class="field"><label>Disease %</label><input type="number" min="0" max="100" step="0.1" name="disease_pct"></div></div><div class="field"><label>Berry, skin and seed condition</label><textarea name="condition_notes"></textarea></div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
fields.cellar_lot=()=>`<div class="field-row"><div class="field"><label>Cellar lot code</label><input name="code" required placeholder="2026-GRC-C01"></div><div class="field"><label>Name</label><input name="name" required placeholder="Grecanico 2026"></div></div><div class="field-row"><div class="field"><label>Started</label><input type="datetime-local" name="started_at" value="${today()}T12:00"></div><div class="field"><label>Stage</label><select name="stage"><option value="must">Must</option><option value="fermentation">Fermentation</option><option value="malo">Malo</option><option value="aging">Aging</option><option value="bottled">Bottled</option><option value="closed">Closed</option></select></div></div><div class="field-row"><div class="field"><label>Fruit kg</label><input type="number" step="0.1" name="fruit_kg"></div><div class="field"><label>Initial liters</label><input type="number" step="0.1" name="initial_l"></div></div><details><summary>More details</summary><div class="field-row"><div class="field"><label>Harvest lot</label><input name="harvest_lot_reference"></div><div class="field"><label>Variety</label><input name="variety_summary"></div></div><div class="field"><label>Responsible</label><input name="responsible"></div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
fields.blend_plan=()=>`<div class="field-row"><div class="field"><label>Blend code</label><input name="code" required placeholder="2026-BAIAMONTE"></div><div class="field"><label>Wine / blend name</label><input name="name" required placeholder="Baiamonte Rosso 2026"></div></div><div class="field"><label>Components and quantities</label><textarea name="components_text" required placeholder="Nerello Mascalese — 900 kg (60%)&#10;Nerello Cappuccio — 450 kg (30%)&#10;Grenache — 150 kg (10%)"></textarea><small>One variety per line. Include kg and percentage so the cellar has one clear instruction.</small></div><div class="field-row"><div class="field"><label>Total grapes planned (kg)</label><input type="number" step="0.1" min="0" name="target_grapes_kg"></div><div class="field"><label>Crate size (kg)</label><input type="number" step="0.1" min="1" name="crate_weight_kg" value="15"></div></div><div class="field-row"><div class="field"><label>Expected finished-wine yield (L/kg grapes)</label><input type="number" step="0.001" min="0" name="expected_yield_l_per_kg" placeholder="0.700"><small>Estimated wine L = grape kg × this factor. Typical red wine: 0.67–0.70 L/kg. This is production yield, not wine mass.</small></div><div class="field"><label>Target wine (L)</label><input type="number" step="0.1" min="0" name="target_volume_l"></div><div class="field"><label>Target bottles</label><input type="number" step="1" min="0" name="planned_bottles"></div></div><div class="field-row"><div class="field"><label>Planned blend date</label><input type="date" name="planned_blend_date" value="${today()}"></div><div class="field"><label>Decision status</label><select name="decision_status"><option value="draft">Draft</option><option value="review">Enologist review</option><option value="approved">Approved</option><option value="completed">Completed</option></select></div></div><div class="field"><label>Target style / objective</label><textarea name="target_style" placeholder="Freshness, tannin, color, acidity, aging goal…"></textarea></div><div class="field-row"><div class="field"><label>Approved by</label><input name="approved_by"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div></div>`;
fields.fermentation=()=>`<div class="field"><label>Cellar lot</label><select name="wine_lot_id">${choices(state.reference.wine_lots,'id','code','Choose lot')}</select></div><div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="observed_at" required value="${today()}T12:00"></div><div class="field"><label>Temperature °C</label><input type="number" step="0.1" name="temp_c"></div></div><div class="field-row"><div class="field"><label>Density / SG</label><input type="number" step="0.0001" name="density_sg"></div><div class="field"><label>°Brix</label><input type="number" step="0.1" name="brix"></div><div class="field"><label>pH</label><input type="number" step="0.01" name="ph"></div></div><div class="field"><label>Observation or action</label><textarea name="sensory_observation"></textarea></div><details><summary>Addition or next check</summary><div class="field"><label>Addition / action</label><input name="addition_action"></div><div class="field-row"><div class="field"><label>Quantity</label><input type="number" step="0.001" name="quantity"></div><div class="field"><label>Unit</label><input name="unit"></div></div><div class="field"><label>Next check</label><input type="datetime-local" name="next_check_at"></div></details>`;
fields.equipment=()=>`<div class="field-row"><div class="field"><label>Date</label><input type="date" name="event_date" required value="${today()}"></div><div class="field"><label>Equipment</label><input name="asset_name" required placeholder="Sprayer, press, pump…"></div></div><div class="field-row"><div class="field"><label>Status before use</label><select name="pre_use_status"><option>Ready</option><option>Hold</option><option>Maintenance</option></select></div><div class="field"><label><input type="checkbox" name="released"> Clean and released</label></div></div><div class="field"><label>Cleaning or maintenance done</label><textarea name="maintenance_action"></textarea></div><details><summary>More details</summary><div class="field"><label>Sanitation method</label><input name="sanitation_method"></div><div class="field-row"><div class="field"><label>Released by</label><input name="released_by"></div><div class="field"><label>Next due</label><input type="date" name="next_due_date"></div></div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
function blockField(){return `<div class="field"><label>Block</label><select name="block_id"><option value="">All / none</option>${(state.reference?.blocks||[]).map(b=>`<option value="${b.id}">${esc(b.code)} — ${esc(b.name)}</option>`).join('')}</select></div>`}function categoryField(){return `<div class="field"><label>Category</label><select name="category">${state.reference.categories.map(c=>`<option value="${c}">${c.replace('_',' ')}</option>`).join('')}</select></div>`}
function configureLaborEntryForm(draft={}){const form=$('entryForm'),worker=form?.querySelector('[data-labor-worker]'),custom=form?.querySelector('[data-labor-custom-worker]'),mode=form?.querySelector('[data-labor-mode]'),classification=form?.querySelector('[data-labor-class]'),hourly=form?.querySelector('[data-labor-hourly]'),fixed=form?.querySelector('[data-labor-fixed]');if(!form||!worker||!custom||!mode||!classification)return;const requested=String(draft?.person_or_crew||'').trim();if(requested){const option=[...worker.options].find(item=>item.value.toLowerCase()===requested.toLowerCase());if(option)worker.value=option.value;else{worker.value='__other__';custom.value=requested}}const syncWorker=()=>{const show=worker.value==='__other__';custom.hidden=!show;custom.disabled=!show;custom.required=show;if(show&&!custom.value)custom.focus()},syncMode=()=>{const isFixed=mode.value==='fixed_job';hourly.hidden=isFixed;fixed.hidden=!isFixed;hourly.querySelectorAll('input,select,textarea').forEach(input=>{input.disabled=isFixed;input.required=!isFixed&&input.name==='regular_hours'});fixed.querySelectorAll('input,select,textarea').forEach(input=>{input.disabled=!isFixed;input.required=isFixed})},syncClass=()=>{const seasonal=classification.value==='seasonal_hourly';form.elements.role.value=seasonal?'Seasonal labor':'Contractor';form.elements.payroll_scope.value='contractor'};worker.onchange=syncWorker;mode.onchange=syncMode;classification.onchange=syncClass;syncWorker();syncMode();syncClass()}
function openEntry(type,draft=null,intakeId=null){state.entry=type;state.intakeItemId=intakeId;const titles={task:'Plan a task',activity:'Log work',harvest:'Add harvest lot',purchase:'Add purchase invoice',sale:'Add sales invoice',cash:'Record cash movement',cellar:'Cellar operation',cellar_lot:'Start cellar lot',blend_plan:'Plan a vintage blend',fermentation:'Fermentation check',enology_profile:'Set enology process',enology_addition:'Plan or record additive',equipment:'Equipment & sanitation',maturity:'Grape maturity sample',scouting:'Observation',phenology:'Growth stage',treatment:'Treatment record',lab:'Laboratory result',labor:'Labor or contractor service',inventory:'Inventory count',olive:'Olive record',issue:'Issue or decision'},photoTypes=new Set(['activity','harvest','cellar','cellar_lot','blend_plan','fermentation','equipment','maturity','scouting','phenology','treatment','lab','labor','olive','issue']),labResults=type==='lab'&&Array.isArray(draft?.results)?draft.results.filter(item=>item&&typeof item==='object'):[];$('dialogTitle').textContent=titles[type]+(intakeId?' — review AI draft':'');$('formFields').innerHTML=fields[type]()+(!labResults.length?'':`<section class="suggested-results"><b>${labResults.length} extracted laboratory results</b>${labResults.map(item=>`<div><span>${esc(item.analyte_name||item.analyte_code||'Analyte')}</span><strong>${esc(item.numeric_value??item.text_value??'—')} ${esc(item.unit||'')}</strong></div>`).join('')}<input type="hidden" name="results_json" value="${esc(JSON.stringify(labResults))}"><small>All listed results will be saved together after this final check.</small></section>`)+(!photoTypes.has(type)?'':`<div class="field photo-field"><label>Photos or supporting document (optional)</label><input type="file" name="attachments" accept="image/*,.pdf" multiple><small>Add a field photo, screenshot, instruction, timesheet or report to this record.</small></div>`);const values=labResults.length?{...draft,...labResults[0]}:draft;if(values&&typeof values==='object')for(const[key,value]of Object.entries(values)){const control=$('entryForm').elements.namedItem(key);if(!control||value==null)continue;if(control.type==='checkbox')control.checked=Boolean(value);else if(control.tagName==='SELECT'&&![...control.options].some(option=>option.value===String(value)))continue;else control.value=Array.isArray(value)?value.join('\n'):String(value)}if(type==='labor')configureLaborEntryForm(values||{});if(type==='scouting')configureScoutingEntryForm();if(type==='harvest')window.configureHarvestEntryForm?.(values||{});$('entryDialog').showModal()}
