document.addEventListener('click',event=>{
  const closeIntake=event.target.closest('[data-close-intake]');
  if(closeIntake){event.preventDefault();closeIntakeReview();return}
  const reject=event.target.closest('[data-intake-reject]');
  if(reject){event.preventDefault();openIntakeRejection(reject.dataset.intakeReject,reject.dataset.intakeTitle||'Incoming information');return}
  const closeReject=event.target.closest('[data-close-reject-intake]');
  if(closeReject){event.preventDefault();$('rejectIntakeDialog')?.close('cancel');return}
  const closeDialog=event.target.closest('[data-close-dialog]');
  if(closeDialog){event.preventDefault();closeEntry()}
});
