const renderUrgentFocusBase=renderUrgentFocus
renderUrgentFocus=function(){
  renderUrgentFocusBase()
  const node=$('urgentFocus')
  if(!node||node.hidden)return
  const finding=node.querySelector('.urgent-findings'),title=finding?.querySelector('b')?.textContent||'Vineyard alert',message=finding?.querySelector('p')?.textContent||''
  const nonCistern=(state.alerts||[]).some(row=>['critical','warning'].includes(row.severity)&&!String(row.alert_type||'').includes('cistern'))
  const icon=node.querySelector('.urgent-thumb span')
  if(icon&&nonCistern)icon.textContent='🚨'
  const ticker=document.createElement('div')
  ticker.className='urgent-alert-ticker'
  ticker.innerHTML=`<span>${esc(`${title} · ${message} · ${title} · ${message}`)}</span>`
  node.append(ticker)
}

