const renderAdminControlCore=renderAdminControl
renderAdminControl=function(){
  renderAdminControlCore()
  updateAdminUptime()
  const queue=$('adminTimesheetReviews')?.querySelector('.worker-admin-queue')
  if(queue){
    const heading=queue.querySelector('.timesheet-review-heading b'),subheading=queue.querySelector('.timesheet-review-heading small')
    if(heading)heading.textContent='Labor & services payment queue'
    if(subheading)subheading.textContent=subheading.textContent.replace('Approval locks the hours','Approved inbound timesheets are paid as one block; their daily records remain available for audit')
    groupWorkerPaymentQueue(queue,state.adminControl?.worker_submissions||[])
    for(const card of queue.querySelectorAll('[data-worker-submission]')){
      const row=(state.adminControl?.worker_submissions||[]).find(item=>String(item.id)===String(card.dataset.workerSubmission))
      if(!row)continue
      const hours=Number(row.regular_hours||0)+Number(row.overtime_hours||0),chargeOnly=row.work_category==='one_off_charge'||(!row.clock_in_at&&hours===0&&row.expense_amount_eur!=null)
      if(!chargeOnly)continue
      card.classList.add('service-charge')
      const title=card.querySelector(':scope > div > b'),approvedAmount=Number(row.labor_cost_eur||0)+Number(row.other_cost_eur||0)
      if(title)title.textContent=`${row.person_or_crew} · ${row.work_date} · Service ${eur(row.expense_amount_eur)}`
      const rate=card.querySelector('.worker-rate'),presence=card.querySelector('[data-worker-presence]'),output=card.querySelector('.worker-presence-result'),approve=card.querySelector('[data-worker-review="approve"]'),approved=card.querySelector(':scope > div > em')
      if(rate)rate.hidden=true
      if(presence)presence.hidden=true
      if(output)output.textContent=row.approval_status==='approved'?'Service is queued with this worker’s other payments':'Receipt and service details require approval'
      if(approve)approve.textContent='Approve service & queue'
      if(approved)approved.textContent=`Approved & locked · ${eur(approvedAmount||row.expense_amount_eur)}${row.pay_due_date?` · due ${row.pay_due_date}`:''}`
    }
  }
  const people=state.adminControl?.labor_reconciliation||[]
  $('adminLaborPeople')?.querySelectorAll('.labor-person-card').forEach(card=>{
    const person=people.find(item=>String(item.key)===String(card.dataset.laborPerson))
    if(!person)return
    const totals=person.totals||{},yearStrip=card.querySelector('.labor-year-strip')
    if(yearStrip&&!card.querySelector('.labor-payment-totals'))yearStrip.insertAdjacentHTML('beforebegin',`<div class="labor-payment-totals"><span><small>Paid this year</small><b>${eur(totals.year_paid_eur)}</b></span><span class="${Number(totals.year_due_eur||0)>0?'amount-due':''}"><small>Total due</small><b>${eur(totals.year_due_eur)}</b></span></div>`)
    const actions=card.querySelector('header .admin-panel-actions')
    if(!actions)return
    if(person.identified===false&&!actions.querySelector('[data-reassign-worker]')){
      const button=document.createElement('button')
      button.type='button';button.className='secondary';button.dataset.reassignWorker=person.name;button.textContent='Identify worker'
      button.onclick=async()=>{const name=prompt(`Assign all records for ${person.name} to:`, '');if(!name?.trim())return;button.disabled=true;try{const result=await api('api/v1/admin/labor/reassign-worker',{method:'POST',body:JSON.stringify({current_name:person.name,new_name:name.trim()})});toast(`${result.records_updated} records assigned to ${result.to}`);await loadAdminControl()}catch(error){toast(error.message)}finally{button.disabled=false}}
      actions.prepend(button)
    }else if(person.identified===true&&!person.home_assistant_linked&&!actions.querySelector('[data-link-ha-person]')){
      const button=document.createElement('button')
      button.type='button';button.className='secondary';button.dataset.linkHaPerson=person.key;button.textContent='Link Home Assistant'
      button.onclick=()=>openLaborIdentityLink(person)
      actions.prepend(button)
    }
  })
}

