async function loadTreatmentProgram(cropScope){
  if(!['vineyard','olives'].includes(cropScope))return;
  state.treatmentCrop=cropScope;
  try{localStorage.setItem('baiamonte-treatment-crop',cropScope)}catch{}
  try{
    const params=new URLSearchParams({year:String(state.year),crop_scope:cropScope});if(state.treatmentPlanningWaterL!=null)params.set('planning_water_l',String(state.treatmentPlanningWaterL));if(state.treatmentEquipment)params.set('equipment',state.treatmentEquipment);
    state.treatmentDashboard=await api(`api/v1/treatments/dashboard?${params}`);
    const basis=state.treatmentDashboard?.product_guidance?.mixture?.planning_basis||{};state.treatmentPlanningWaterL=Number(basis.water_l||state.treatmentPlanningWaterL||400);state.treatmentEquipment=String(basis.equipment?.equipment_id||state.treatmentEquipment||'');
    state.treatments=state.treatmentDashboard?.treatments||[];
    renderTreatments();
  }catch(error){toast(error.message)}
}
document.querySelectorAll('[data-treatment-crop]').forEach(button=>button.addEventListener('click',()=>loadTreatmentProgram(button.dataset.treatmentCrop)));
document.querySelector('[data-open-olive-treatments]')?.addEventListener('click',()=>{
  document.querySelector('.tabs button[data-view="treatments"]')?.click();
  loadTreatmentProgram('olives');
});
